insert into public.deals (external_key, date, date_text, kind, asset_class, sport, target, target_kind, target_country, target_team_id, target_company_id, investor, investor_type, investor_company_id, investor_id, seller, stake_pct, amount, currency, valuation, valuation_currency, headline, summary, source_name, source_url, source)
  values ('deal:afc-bournemouth:ryan-sports-ventures:september-2023', null, 'September 2023', 'minority_investment', 'sports', 'football', 'AFC Bournemouth', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--afc-bournemouth'), null, 'Ryan Sports Ventures', 'family_office', (select id from public.companies where lower(name) = lower('Ryan Sports Ventures') limit 1), (select id from public.sports_investors where lower(name) = lower('Ryan Sports Ventures') limit 1), null, null, null, null, null, null, 'Ryan Sports Ventures takes minority stake in Black Knight Football Club', 'The Chicago-based Ryan family''s sports investment arm, minority owners of the Chicago Bears, acquired an undisclosed minority stake in BKFC, the vehicle that owns AFC Bournemouth.', 'Sportico', 'https://www.sportico.com/business/sales/2023/chicago-bears-investors-buy-bill-foleys-bournemouth-1234739606/', 'web_research')
