  values ('deal:afc-bournemouth:goldman-sachs:december-2024', null, 'December 2024', 'debt_financing', 'sports', 'football', 'AFC Bournemouth', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--afc-bournemouth'), null, 'Goldman Sachs', 'private_credit', (select id from public.companies where lower(name) = lower('Goldman Sachs') limit 1), (select id from public.sports_investors where lower(name) = lower('Goldman Sachs') limit 1), null, null, null, null, null, null, 'AFC Bournemouth establishes Goldman Sachs senior secured credit facility', 'Proceeds of a senior secured credit facility with Goldman Sachs put in place in December 2024 were used to repay £29.4m of City National Bank loans and £6.4m owed to Black Knight Football Club UK Limited, per the club''s FY2025 accounts.', 'The Esk (analysis of AFC Bournemouth Limited FY2025 accounts)', 'https://theesk.org/2026/05/11/the-analysis-series-afc-bournemouth-limited-annual-report-and-financial-statements-for-the-year-ended-30-june-2025/', 'web_research')
